#!/usr/bin/env python3
"""Render the separately authored 250-branch review; no game writes."""
import copy,json,pathlib,re,collections
HERE=pathlib.Path(__file__).resolve().parent
BOOK=HERE.parents[1]
SRC=BOOK/'baseline/source'
base=[json.loads(x) for x in (HERE/'baseline.jsonl').read_text().splitlines()]
notes={}
for p in sorted(HERE.glob('notes-*.txt')):
 for row in p.read_text().splitlines():
  key,disposition,assessment,ai,counter=row.split('|')
  notes['TRAINER_'+key]={'disposition':disposition,'assessment':assessment,'ai':ai,'counterplay':counter,'review_block':p.stem}
assert len(base)==len(notes)==250
assert set(notes)=={x['trainer'] for x in base}
notes['TRAINER_QUINCY']['disposition']='REVISE'
